<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import { collection, addDoc, deleteDoc, doc, onSnapshot, query, updateDoc, where } from 'firebase/firestore'
import { createUserWithEmailAndPassword, onAuthStateChanged, sendPasswordResetEmail, signInWithEmailAndPassword, signOut } from 'firebase/auth'
import { auth, db, firebaseReady } from './firebase'

const user = ref(null), page = ref('首頁'), tab = ref('清單'), people = ref([]), events = ref([])
const email = ref(''), password = ref(''), authMode = ref('login'), authError = ref(''), toast = ref(''), homeCity = ref([]), homeDistrict = ref([]), peopleCity = ref([]), peopleDistrict = ref([]), pickerCity = ref([]), pickerDistrict = ref([]), searchPeople = ref('')
const form = ref({ title: '', due: today(), note: '', contactIds: [] }), contactForm = ref({ name: '', nickname: '', phone: '', email: '', city: '', district: '', note: '' })
const editing = ref(null), editingPerson = ref(null), reasonAction = ref(null), reason = ref(''), batchModal = ref(null), batchMode = ref('single'), pageSize = ref(10), pickerSearch = ref('')
const countyDistricts = {
  '臺北市':['中正區','大同區','中山區','松山區','大安區','萬華區','信義區','士林區','北投區','內湖區','南港區','文山區'],
  '新北市':['板橋區','三重區','中和區','永和區','新莊區','新店區','土城區','蘆洲區','汐止區','樹林區','淡水區','三峽區'],
  '桃園市':['桃園區','中壢區','大溪區','楊梅區','蘆竹區','龜山區','八德區','平鎮區'],
  '臺中市':['中區','東區','西區','南區','北區','西屯區','南屯區','北屯區'],
  '臺南市':['中西區','東區','南區','北區','安平區','安南區'],
  '高雄市':['新興區','前金區','苓雅區','鹽埕區','鼓山區','左營區','楠梓區','三民區','前鎮區','小港區'],
  '基隆市':['仁愛區','信義區','中正區','中山區','安樂區','暖暖區','七堵區'],
  '新竹市':['東區','北區','香山區'], '嘉義市':['東區','西區'],
  '新竹縣':['竹北市','竹東鎮','新埔鎮','關西鎮'], '苗栗縣':['苗栗市','頭份市','竹南鎮'],
  '彰化縣':['彰化市','員林市','鹿港鎮'], '南投縣':['南投市','草屯鎮','埔里鎮'],
  '雲林縣':['斗六市','虎尾鎮','西螺鎮'], '嘉義縣':['太保市','朴子市','民雄鄉'],
  '屏東縣':['屏東市','潮州鎮','東港鎮'], '宜蘭縣':['宜蘭市','羅東鎮','頭城鎮'],
  '花蓮縣':['花蓮市','吉安鄉','玉里鎮'], '臺東縣':['臺東市','成功鎮','關山鎮'],
  '澎湖縣':['馬公市','湖西鄉'], '金門縣':['金城鎮','金湖鎮'], '連江縣':['南竿鄉','北竿鄉']
}
const cities = Object.keys(countyDistricts)
function today(){ const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}` }
function notify(s){toast.value=s;setTimeout(()=>toast.value='',2800)}
function dayDiff(date){return Math.round((new Date(`${date}T00:00:00+08:00`)-new Date(`${today()}T00:00:00+08:00`))/86400000)}
function stateOf(e){ if(e.deletedAt)return '刪除';if(e.status==='完成'||e.status==='取消')return e.status;if(dayDiff(e.due)<0)return '逾時';return '清單' }
const visibleEvents=computed(()=>events.value.filter(e=>stateOf(e)===tab.value).filter(e=>{
  if(!homeCity.value.length&&!homeDistrict.value.length)return true
  if(!e.contacts?.length)return true
  const contacts=e.contacts.map(c=>people.value.find(p=>p.id===c.id)||c)
  // Keep incomplete contact records visible, but only include a missing district for its selected city.
  return contacts.every(c=>matchesArea(c,homeCity.value,homeDistrict.value))
}).sort((a,b)=>tab.value==='逾時'?dayDiff(a.due)-dayDiff(b.due):a.due.localeCompare(b.due)))
const shownEvents=computed(()=>visibleEvents.value.slice(0,pageSize.value))
const filteredPeople=computed(()=>people.value.filter(p=>(`${p.name} ${p.nickname||''}`).toLowerCase().includes(searchPeople.value.toLowerCase())).filter(p=>matchesArea(p,peopleCity.value,peopleDistrict.value)))
const pickerPeople=computed(()=>people.value.filter(p=>(`${p.name} ${p.nickname||''}`).toLowerCase().includes(pickerSearch.value.toLowerCase())).filter(p=>matchesArea(p,pickerCity.value,pickerDistrict.value)))
const homeDistrictOptions=computed(()=>homeCity.value.flatMap(c=>(countyDistricts[c]||[]).map(d=>`${c}/${d}`)))
const peopleDistrictOptions=computed(()=>peopleCity.value.flatMap(c=>(countyDistricts[c]||[]).map(d=>`${c}/${d}`)))
const pickerDistrictOptions=computed(()=>pickerCity.value.flatMap(c=>(countyDistricts[c]||[]).map(d=>`${c}/${d}`)))
function matchesArea(person, selectedCities, selectedDistricts){
  if(!selectedCities.length&&!selectedDistricts.length)return true
  if(!person.city)return true
  if(!person.district)return selectedCities.includes(person.city)
  if(selectedDistricts.length)return selectedDistricts.includes(`${person.city}/${person.district}`)
  return selectedCities.includes(person.city)
}
watch(homeCity, value=>{homeDistrict.value=homeDistrict.value.filter(d=>value.includes(d.split('/')[0]))})
watch(peopleCity, value=>{peopleDistrict.value=peopleDistrict.value.filter(d=>value.includes(d.split('/')[0]))})
watch(pickerCity, value=>{pickerDistrict.value=pickerDistrict.value.filter(d=>value.includes(d.split('/')[0]))})
function fullName(p){return `${p.name}${p.nickname?`（${p.nickname}）`:''}`}
function contactLabel(c){const p=people.value.find(x=>x.id===c.id)||c;return `${fullName(p)}${!p.city?'　無縣市':!p.district?'　無行政區':`　${p.city} ${p.district}`}`}
function dateLabel(s){return s?.replaceAll('-','/')||''}
function localEvents(){try{events.value=JSON.parse(localStorage.getItem(`events:${user.value.uid}`)||'[]');people.value=JSON.parse(localStorage.getItem(`people:${user.value.uid}`)||'[]')}catch{events.value=[];people.value=[]}}
function saveLocal(){localStorage.setItem(`events:${user.value.uid}`,JSON.stringify(events.value));localStorage.setItem(`people:${user.value.uid}`,JSON.stringify(people.value))}
let unsubEvents,unsubPeople
function subscribeData(){if(!firebaseReady){localEvents();return}
  unsubEvents=onSnapshot(query(collection(db,'events'),where('ownerId','==',user.value.uid)),s=>events.value=s.docs.map(x=>({id:x.id,...x.data()})))
  unsubPeople=onSnapshot(query(collection(db,'contacts'),where('ownerId','==',user.value.uid)),s=>people.value=s.docs.map(x=>({id:x.id,...x.data()})))
}
function stopSubs(){unsubEvents?.();unsubPeople?.();unsubEvents=unsubPeople=null}
async function saveEvent(e){if(firebaseReady){const {id,...data}=e;id?await updateDoc(doc(db,'events',id),data):await addDoc(collection(db,'events'),data)}else{if(!e.id)e.id=crypto.randomUUID();const i=events.value.findIndex(x=>x.id===e.id);i<0?events.value.push(e):events.value.splice(i,1,e);saveLocal()}}
async function removeEvent(e){if(firebaseReady)await deleteDoc(doc(db,'events',e.id));else{events.value=events.value.filter(x=>x.id!==e.id);saveLocal()}}
async function savePerson(p){if(firebaseReady){const {id,...data}=p;id?await updateDoc(doc(db,'contacts',id),data):await addDoc(collection(db,'contacts'),data)}else{if(!p.id)p.id=crypto.randomUUID();const i=people.value.findIndex(x=>x.id===p.id);i<0?people.value.push(p):people.value.splice(i,1,p);saveLocal()}}
async function deletePerson(p){const used=events.value.filter(e=>e.contacts?.some(c=>c.id===p.id));if(!confirm(`此聯絡人關聯 ${used.length} 筆事件。事件將保留聯絡人資料快照。確定刪除？`))return
  for(const e of used){e.contacts=e.contacts.map(c=>c.id===p.id?{...p,id:p.id}:c);await saveEvent(e)}
  if(firebaseReady)await deleteDoc(doc(db,'contacts',p.id));else{people.value=people.value.filter(x=>x.id!==p.id);saveLocal()}notify('聯絡人已刪除')}
async function authenticate(){authError.value='';try{if(!firebaseReady){if(!email.value||!password.value)throw Error('請輸入電子郵件與密碼');user.value={uid:email.value.toLowerCase(),email:email.value};localEvents();return}
  user.value=authMode.value==='register'?await createUserWithEmailAndPassword(auth,email.value,password.value).then(x=>x.user):await signInWithEmailAndPassword(auth,email.value,password.value).then(x=>x.user)
}catch(e){authError.value=humanError(e.code)||e.message}}
function humanError(code){return ({'auth/invalid-credential':'電子郵件或密碼不正確','auth/email-already-in-use':'此電子郵件已註冊','auth/invalid-email':'電子郵件格式不正確','auth/weak-password':'密碼未符合登入服務要求','auth/too-many-requests':'嘗試次數過多，請稍後再試'})[code]}
async function resetPassword(){if(!email.value){authError.value='請先輸入電子郵件';return}try{await sendPasswordResetEmail(auth,email.value);notify('重設密碼郵件已送出')}catch(e){authError.value=humanError(e.code)||'無法寄送重設郵件'}}
async function logout(){stopSubs();if(firebaseReady)await signOut(auth);user.value=null;events.value=[];people.value=[]}
function beginEvent(e=null){editing.value=e?structuredClone(e):null;form.value=e?{title:e.title,due:e.due,note:e.note||'',contactIds:e.contacts?.map(c=>c.id)||[]}: {title:'',due:today(),note:'',contactIds:[]};page.value='事件'}
function askConfirmBatch(){const selected=people.value.filter(p=>form.value.contactIds.includes(p.id));if(selected.length>1)batchModal.value=selected;else submitEvent()}
async function submitEvent(){try{const selected=people.value.filter(p=>form.value.contactIds.includes(p.id));const base={title:form.value.title.trim(),due:form.value.due,note:form.value.note,ownerId:user.value.uid,updatedAt:new Date().toISOString()};
  if(editing.value){const target=editing.value;const patch={...target,...base,contacts:selected.map(p=>({id:p.id}))};await saveEvent(patch);notify('事件已更新')}
  else {const batchId=selected.length>1?crypto.randomUUID():null;const targets=selected.length?selected:[null];for(const p of targets)await saveEvent({...base,id:null,status:'未處理',contacts:p?[{id:p.id}]:[],batchId,createdAt:new Date().toISOString()});notify(`已建立 ${targets.length} 筆事件`)}
  form.value={title:'',due:today(),note:'',contactIds:[]};editing.value=null;batchModal.value=null
}catch(e){notify(`儲存失敗：${e.message}`)}}
async function setState(e,status){reasonAction.value={event:e,status};reason.value=''}
async function commitState(){const {event:e,status}=reasonAction.value;try{if(status==='刪除')await saveEvent({...e,deletedAt:new Date().toISOString(),reason:reason.value,status:e.status});else await saveEvent({...e,status,reason:status==='逾時'?'超過期限':reason.value,deletedAt:null});reasonAction.value=null;notify(`事件已${status}`)}catch(e){notify(`操作失敗：${e.message}`)}}
function restore(e){if(dayDiff(e.due)<0){editing.value=structuredClone(e);form.value={title:e.title,due:today(),note:e.note||'',contactIds:e.contacts?.map(c=>c.id)||[]};page.value='事件';notify('請設定今天或未來的期限後儲存，即可復原')}else saveEvent({...e,status:'未處理',deletedAt:null,reason:''}).then(()=>notify('事件已復原'))}
async function startPerson(p=null){editingPerson.value=p?structuredClone(p):null;contactForm.value=p?{...p}:{name:'',nickname:'',phone:'',email:'',city:'',district:'',note:''};await nextTick();document.querySelector('.people-form')?.scrollIntoView({behavior:'smooth',block:'start'})}
async function submitPerson(){try{await savePerson({...contactForm.value,id:editingPerson.value?.id,ownerId:user.value.uid});if(!editingPerson.value){contactForm.value={name:'',nickname:'',phone:'',email:'',city:'',district:'',note:''};notify('聯絡人已新增')}else notify('聯絡人已更新');editingPerson.value=null}catch(e){notify(`儲存失敗：${e.message}`)}}
watch(tab,()=>pageSize.value=10)
let authListener
onMounted(()=>{if(firebaseReady)authListener=onAuthStateChanged(auth,u=>{stopSubs();user.value=u;if(u)subscribeData()})})
onUnmounted(()=>{stopSubs();authListener?.()})
</script>

<template>
<div v-if="!user" class="auth-screen"><section class="auth-card"><div class="brand-mark">日</div><p class="eyebrow">DAYMARK · PERSONAL PLANNER</p><h1>把重要的事，<br>放在眼前。</h1><p class="muted mb-4">為每個期限留一個清楚的位置。</p><div v-if="!firebaseReady" class="alert alert-warning small">Firebase 尚未設定，目前以本機預覽模式體驗；資料只存在這個瀏覽器。</div><form @submit.prevent="authenticate"><label class="form-label">電子郵件</label><input v-model="email" type="email" required class="form-control mb-3" placeholder="you@example.com"><label class="form-label">密碼</label><input v-model="password" type="password" required class="form-control mb-3" placeholder="輸入密碼"><p v-if="authError" class="text-danger small">{{authError}}</p><button class="btn btn-dark w-100 py-2">{{authMode==='login'?'登入':'建立帳號'}}</button></form><div class="d-flex justify-content-between mt-3 small"><button class="link-button" @click="authMode=authMode==='login'?'register':'login'">{{authMode==='login'?'建立帳號':'已有帳號？登入'}}</button><button v-if="authMode==='login'&&firebaseReady" class="link-button" @click="resetPassword">忘記密碼</button></div></section></div>
<div v-else class="app-shell">
  <header class="topbar"><a class="wordmark" @click="page='首頁'"><span class="brand-mark mini">日</span><span>日常優先序</span></a><nav class="main-nav"><button v-for="item in ['首頁','事件','聯絡人']" :key="item" :class="['nav-item',page===item?'active':'']" @click="item==='事件'?beginEvent():page=item">{{item}}</button></nav><div class="account-menu"><span class="account-avatar">{{(user.email||'U').slice(0,1).toUpperCase()}}</span><div class="dropdown"><button class="link-button" data-bs-toggle="dropdown" aria-expanded="false">{{user.email}}　⌄</button><ul class="dropdown-menu dropdown-menu-end"><li><span class="dropdown-item-text small">{{user.email}}</span></li><li><hr class="dropdown-divider"></li><li><button class="dropdown-item" @click="logout">登出</button></li></ul></div></div></header>
  <main class="container-fluid content-wrap">
    <template v-if="page==='首頁'"><section class="welcome-row"><div><p class="eyebrow">YOUR DAY, IN ORDER</p><h1>今天，先處理重要的。</h1><p class="muted">把注意力留給眼前最值得完成的事。</p></div><button class="btn btn-dark create-btn" @click="beginEvent()">＋ 建立事件</button></section>
      <section class="stat-strip"><div><span class="stat-number">{{events.filter(e=>stateOf(e)==='清單').length}}</span><span class="stat-label">待處理</span></div><div><span class="stat-number urgent-text">{{events.filter(e=>stateOf(e)==='逾時').length}}</span><span class="stat-label">逾時待跟進</span></div><div class="date-chip">{{new Date().toLocaleDateString('zh-TW',{year:'numeric',month:'long',day:'numeric',weekday:'long'})}}</div></section>
      <section class="filter-bar"><div class="filter-title">依區域安排 <span>可多選</span></div><select multiple v-model="homeCity" class="form-select multi-select" aria-label="選擇縣市"><option v-for="c in cities" :key="c">{{c}}</option></select><select multiple v-model="homeDistrict" class="form-select multi-select" aria-label="選擇行政區"><option v-for="d in homeDistrictOptions" :key="d" :value="d">{{d.replace('/',' · ')}}</option></select><div class="selected-filters"><button v-if="homeCity.length||homeDistrict.length" class="link-button clear-filter" @click="homeCity=[];homeDistrict=[]">顯示全部地區 ×</button></div></section>
      <div class="task-tabs"><button v-for="t in ['清單','逾時','刪除','完成','取消']" :key="t" :class="['task-tab',tab===t?'selected':'',t==='逾時'?'tab-danger':'']" @click="tab=t">{{t}}<span>{{events.filter(e=>stateOf(e)===t).length}}</span></button></div>
      <div v-if="!shownEvents.length" class="empty-state"><div class="empty-icon">✳</div><h3>{{tab==='清單'?'留一點空間給自己':'目前沒有這類事件'}}</h3><p class="muted">{{tab==='清單'?'建立一件要記得的事，期限到了就不會錯過。':'有需要時，事件會出現在這裡。'}}</p><button v-if="tab==='清單'" class="btn btn-outline-dark" @click="beginEvent()">建立第一個事件</button></div>
      <div v-else class="event-list"><article v-for="e in shownEvents" :key="e.id" class="event-card" :class="{'urgent-card':tab==='清單'&&dayDiff(e.due)<=3,'overdue-card':tab==='逾時'}"><div class="countdown"><template v-if="stateOf(e)==='清單'"><strong>{{dayDiff(e.due)}}</strong><small>天</small></template><template v-else><strong class="state-word">{{stateOf(e)==='逾時'?`${Math.abs(dayDiff(e.due))}天`:stateOf(e)}}</strong><small v-if="stateOf(e)==='逾時'">逾時</small></template></div><div class="event-main"><div class="event-heading"><h3>{{e.title}}</h3><span v-if="e.batchId" class="batch-pill" @click="batchModal=events.filter(x=>x.batchId===e.batchId)">同批 · 查看</span><span v-if="tab==='清單'&&dayDiff(e.due)<=3" class="urgent-pill">{{dayDiff(e.due)===0?'今天到期':'即將到期'}}</span></div><div class="event-meta"><span>期限　{{dateLabel(e.due)}}</span><span v-if="e.contacts?.length">{{e.contacts.map(contactLabel).join('、')}}</span></div><p v-if="e.note" class="event-note">{{e.note}}</p><p v-if="e.reason" class="event-note reason-note">{{e.reason}}</p></div><div class="event-actions"><template v-if="['清單','逾時'].includes(tab)"><button class="icon-btn" title="編輯" @click="beginEvent(e)">✎</button><button class="icon-btn done-action" title="完成" @click="setState(e,'完成')">✓</button><button class="icon-btn" title="取消" @click="setState(e,'取消')">↗</button><button class="icon-btn delete-action" title="刪除" @click="setState(e,'刪除')">⌫</button></template><button v-else class="btn btn-sm btn-outline-dark" @click="restore(e)">復原</button></div></article></div><button v-if="shownEvents.length<visibleEvents.length" class="btn btn-load" @click="pageSize+=10">再顯示 10 筆　↓</button>
    </template>
    <template v-else-if="page==='事件'"><section class="page-heading"><p class="eyebrow">NEW EVENT</p><h1>{{editing?'編輯事件':'建立事件'}}</h1><p class="muted">先寫下事件，再選擇要一起追蹤的聯絡人。</p></section><div class="form-layout"><form class="editor-card" @submit.prevent="askConfirmBatch"><label class="form-label">事件名稱 <span class="required">必填</span></label><input v-model="form.title" maxlength="80" required class="form-control" placeholder="例如：準備生日禮物"><div class="character-count">{{80-form.title.length}} 字可輸入</div><label class="form-label mt-4">期限 <span class="required">必填</span></label><div class="date-entry"><input v-model="form.due" type="date" :min="today()" required class="form-control"><div class="quick-date"><button v-for="n in [1,2,3,7,30,90,180,365]" :key="`plus${n}`" type="button" @click="form.due=shiftDate(form.due,n)">+{{n<7?n:n===7?'週':n===30?'月':n===90?'季':n===180?'半年':'年'}}</button><button v-for="n in [1,2,3,7,30,90,180,365]" :key="`minus${n}`" type="button" @click="form.due=shiftDate(form.due,-n)">−{{n<7?n:n===7?'週':n===30?'月':n===90?'季':n===180?'半年':'年'}}</button></div></div><label class="form-label mt-4">事件備註 <span class="optional">選填</span></label><textarea v-model="form.note" maxlength="500" rows="4" class="form-control" placeholder="補充處理資訊…"></textarea><div class="character-count">{{500-form.note.length}} 字可輸入</div><div class="section-divider"></div><label class="form-label">關聯聯絡人 <span class="optional">可不選、多選</span></label><input v-model="pickerSearch" class="form-control mb-2" placeholder="搜尋姓名或暱稱"><div class="picker-filters"><select v-model="pickerCity" multiple class="form-select multi-select"><option v-for="c in cities" :key="c">{{c}}</option></select><select v-model="pickerDistrict" multiple class="form-select multi-select"><option v-for="d in pickerDistrictOptions" :key="d" :value="d">{{d.replace('/',' · ')}}</option></select></div><div class="contact-picker"><label v-for="p in pickerPeople" :key="p.id" class="contact-option"><input v-model="form.contactIds" type="checkbox" :value="p.id"><span class="check-ui"></span><span><b>{{fullName(p)}}</b><small>{{p.city||'無縣市'}} · {{p.district||'無行政區'}}</small></span></label><p v-if="!pickerPeople.length" class="muted text-center py-3">找不到聯絡人，可到聯絡人頁新增。</p></div><p class="small muted mt-2">已選 {{form.contactIds.length}} 位；每位聯絡人將建立一筆獨立事件。</p><div class="form-footer"><button type="button" class="btn btn-link text-secondary" @click="page='首頁'">取消</button><button class="btn btn-dark px-4" :disabled="!form.title.trim()||!form.due">{{editing?'儲存修改':'建立事件'}}</button></div></form><aside class="preview-card"><p class="eyebrow">PREVIEW</p><div class="preview-count"><b>{{dayDiff(form.due||today())}}</b><span>天</span></div><h3>{{form.title||'事件名稱'}}</h3><p>期限　{{dateLabel(form.due||today())}}</p><p class="preview-note">{{form.note||'事件備註會顯示在清單卡片。'}}</p><div v-if="form.contactIds.length" class="preview-contacts">{{people.filter(p=>form.contactIds.includes(p.id)).map(fullName).join('、')}}</div><span class="preview-tag">即時預覽</span></aside></div></template>
    <template v-else><section class="page-heading"><div class="heading-flex"><div><p class="eyebrow">PEOPLE</p><h1>聯絡人</h1><p class="muted">把常聯絡的人整理在一起，依地區更快找到。</p></div><button class="btn btn-dark" @click="startPerson()">＋ 新增聯絡人</button></div></section><div class="people-layout"><form class="editor-card people-form" @submit.prevent="submitPerson"><div class="form-title-row"><h2>{{editingPerson?'編輯聯絡人':'新增聯絡人'}}</h2><button v-if="editingPerson" type="button" class="link-button" @click="startPerson()">新增另一位</button></div><label class="form-label">姓名 <span class="required">必填</span></label><input v-model="contactForm.name" required maxlength="50" class="form-control"><div class="character-count">{{50-contactForm.name.length}} 字可輸入</div><label class="form-label mt-3">暱稱 <span class="optional">選填</span></label><input v-model="contactForm.nickname" maxlength="30" class="form-control"><label class="form-label mt-3">電話 <span class="optional">選填</span></label><input v-model="contactForm.phone" class="form-control"><label class="form-label mt-3">電子郵件 <span class="optional">選填</span></label><input v-model="contactForm.email" type="email" class="form-control"><div class="row mt-3"><div class="col"><label class="form-label">縣市</label><select v-model="contactForm.city" class="form-select"><option value="">選擇縣市</option><option v-for="c in cities" :key="c">{{c}}</option></select></div><div class="col"><label class="form-label">行政區</label><select v-model="contactForm.district" class="form-select" :disabled="!contactForm.city"><option value="">選擇行政區</option><option v-for="d in countyDistricts[contactForm.city]||[]" :key="d">{{d}}</option></select></div></div><label class="form-label mt-3">備註 <span class="optional">選填</span></label><textarea v-model="contactForm.note" maxlength="500" rows="3" class="form-control"></textarea><div class="character-count">{{500-contactForm.note.length}} 字可輸入</div><div class="form-footer"><button v-if="editingPerson" type="button" class="btn btn-link text-danger" @click="deletePerson(editingPerson)">刪除聯絡人</button><span v-else></span><button class="btn btn-dark">{{editingPerson?'儲存修改':'新增聯絡人'}}</button></div></form><section class="people-directory"><div class="directory-tools"><div><h2>所有聯絡人 <span class="count-bubble">{{filteredPeople.length}}</span></h2></div><input v-model="searchPeople" class="form-control" placeholder="搜尋姓名或暱稱"><div class="row"><div class="col"><select v-model="peopleCity" multiple class="form-select multi-select"><option v-for="c in cities" :key="c">{{c}}</option></select></div><div class="col"><select v-model="peopleDistrict" multiple class="form-select multi-select"><option v-for="d in peopleDistrictOptions" :key="d" :value="d">{{d.replace('/',' · ')}}</option></select></div></div></div><div v-if="filteredPeople.length" class="directory-list"><article v-for="p in filteredPeople" :key="p.id" class="person-row"><div class="person-avatar">{{p.name.slice(0,1)}}</div><div class="person-info"><strong>{{fullName(p)}}</strong><span>{{p.city||'無縣市'}} · {{p.district||'無行政區'}} <span v-if="!p.city||!p.district" class="missing-tag">地區未完整</span></span><small>{{p.phone||p.email||'尚未填寫聯絡方式'}}</small></div><button class="icon-btn" @click="startPerson(p)">✎</button></article></div><div v-else class="empty-state compact"><div class="empty-icon">◎</div><h3>還沒有聯絡人</h3><p class="muted">新增常聯絡的人，之後建立事件更方便。</p></div></section></div></template>
  </main><div v-if="toast" class="toast-message">{{toast}}</div>
  <div v-if="batchModal" class="modal-backdrop-custom"><div class="confirm-modal"><button class="modal-close" @click="batchModal=null">×</button><p class="eyebrow">BATCH PREVIEW</p><h2>即將建立 {{batchModal.length}} 筆事件</h2><p class="muted">每位聯絡人會有自己的事件與處理狀態。</p><div class="batch-preview-list"><div v-for="p in batchModal" :key="p.id"><span class="person-avatar tiny">{{p.name.slice(0,1)}}</span>{{fullName(p)}}<small>{{p.city||'無縣市'}} · {{p.district||'無行政區'}}</small></div></div><div class="form-footer"><button class="btn btn-link text-secondary" @click="batchModal=null">返回修改</button><button class="btn btn-dark" @click="submitEvent">確認建立 {{batchModal.length}} 筆</button></div></div></div>
  <div v-if="reasonAction" class="modal-backdrop-custom"><form class="confirm-modal" @submit.prevent="commitState"><button type="button" class="modal-close" @click="reasonAction=null">×</button><p class="eyebrow">UPDATE EVENT</p><h2>{{reasonAction.status==='刪除'?'移至刪除清單':`標記為${reasonAction.status}`}}</h2><p class="muted">{{reasonAction.event.title}}</p><label class="form-label">原因 <span class="optional">選填</span></label><textarea v-model="reason" maxlength="500" rows="3" class="form-control" :placeholder="reasonAction.status==='逾時'?'超過期限':'補充原因…'"></textarea><div class="character-count">{{500-reason.length}} 字可輸入</div><div class="form-footer"><button type="button" class="btn btn-link text-secondary" @click="reasonAction=null">返回</button><button class="btn btn-dark">確認</button></div></form></div>
</div>
</template>

<script>
export default { methods: { shiftDate(date,amount){const d=new Date(`${date||new Date().toISOString().slice(0,10)}T00:00:00`);d.setDate(d.getDate()+amount);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`} } }
</script>


